package com.lixui.input.event;

import com.lixui.input.Key;
import com.lixui.input.Modifiers;

import java.util.Objects;

/**
 * A keyboard key was pressed.
 *
 * @param key pressed key
 * @param modifiers active keyboard modifiers
 * @param repeat true when the event was generated by key repeat
 */
public record KeyPressed(Key key, Modifiers modifiers, boolean repeat) implements InputEvent {
    /**
     * Creates a key press event.
     *
     * @param key pressed key
     * @param modifiers active keyboard modifiers
     * @param repeat true when the event was generated by key repeat
     * @throws NullPointerException if {@code key} or {@code modifiers} is null
     */
    public KeyPressed {
        Objects.requireNonNull(key, "key");
        Objects.requireNonNull(modifiers, "modifiers");
    }
}
